package shop.ultimatesmp.spawn;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assumptions.*;
import org.bukkit.*;import org.bukkit.block.Block;import org.bukkit.entity.Player;import org.bukkit.event.block.*;import org.bukkit.event.player.*;import java.util.*;
class SpawnTest {
 @Test void editPermissionIsRequiredEvenForAnOpAndOnlyInSpawn(){World spawn=mock(World.class),other=mock(World.class);SpawnProtection rules=new SpawnProtection(w->w==spawn);Player p=mock(Player.class);when(p.isOp()).thenReturn(true);Block block=mock(Block.class);when(block.getWorld()).thenReturn(spawn);BlockBreakEvent event=mock(BlockBreakEvent.class);when(event.getPlayer()).thenReturn(p);when(event.getBlock()).thenReturn(block);rules.breakBlock(event);verify(event).setCancelled(true);
  when(p.hasPermission("edit.spawn")).thenReturn(true);BlockBreakEvent allowed=mock(BlockBreakEvent.class);when(allowed.getPlayer()).thenReturn(p);when(allowed.getBlock()).thenReturn(block);rules.breakBlock(allowed);verify(allowed,never()).setCancelled(true);
  when(p.hasPermission("edit.spawn")).thenReturn(false);when(block.getWorld()).thenReturn(other);BlockBreakEvent outside=mock(BlockBreakEvent.class);when(outside.getPlayer()).thenReturn(p);when(outside.getBlock()).thenReturn(block);rules.breakBlock(outside);verify(outside,never()).setCancelled(true);
 }
 @Test void placementAndBucketsUseTheSameExplicitPermission(){World spawn=mock(World.class);SpawnProtection rules=new SpawnProtection(w->w==spawn);Player p=mock(Player.class);Block block=mock(Block.class);when(block.getWorld()).thenReturn(spawn);BlockPlaceEvent place=mock(BlockPlaceEvent.class);when(place.getPlayer()).thenReturn(p);when(place.getBlock()).thenReturn(block);rules.place(place);verify(place).setCancelled(true);PlayerBucketEmptyEvent bucket=mock(PlayerBucketEmptyEvent.class);when(bucket.getPlayer()).thenReturn(p);when(bucket.getBlock()).thenReturn(block);rules.bucketEmpty(bucket);verify(bucket).setCancelled(true);}
 @Test void warmupIgnoresLookingButCancelsMovementOrAnotherWorld(){World a=mock(World.class),b=mock(World.class);Location origin=new Location(a,0,70,0);assertFalse(WarmupPolicy.moved(origin,new Location(a,0,70,0,90,45)));assertTrue(WarmupPolicy.moved(origin,new Location(a,.2,70,0)));assertTrue(WarmupPolicy.moved(origin,new Location(b,0,70,0)));}
 @Test void spawnCoordinatesAreBounded(){assertThrows(IllegalArgumentException.class,()->new SpawnPoint("BlinkSMP-Overworld-02","../world",0,70,0,0,0));assertThrows(IllegalArgumentException.class,()->new SpawnPoint("BlinkSMP-Overworld-02","ultimate_spawn",Double.NaN,70,0,0,0));assertThrows(IllegalArgumentException.class,()->new SpawnPoint("bad","ultimate_spawn",0,70,0,0,0));}
 @Test void sharedMariaDbPointPersistsAndNeverOverwritesAnExistingSetspawn()throws Exception{String url=System.getenv("TEST_SPAWN_JDBC");assumeTrue(url!=null);var source=new org.mariadb.jdbc.MariaDbDataSource(url);source.setUser("root");source.setPassword("disposable");SpawnStore store=new SpawnStore(source);store.initialize();SpawnPoint first=new SpawnPoint("BlinkSMP-Overworld-02","ultimate_spawn",.5,-59,.5,90,0);store.save(first,true);assertEquals(first,store.load());SpawnPoint next=new SpawnPoint("BlinkSMP-Overworld-02","ultimate_spawn",10.5,72,20.5,180,20);store.save(next,false);store.save(first,true);assertEquals(next,store.load());}
}
